// pagerItems devolve as entradas do paginador "three dots": as 3 primeiras
// páginas, a atual com seus vizinhos e as 3 últimas. Lacunas viram 0
// (reticências).
func pagerItems(current, total int) []int {
	show := map[int]bool{}
	for _, p := range []int{1, 2, 3, current - 1, current, current + 1, total - 2, total - 1, total} {
		if p >= 1 && p <= total {
			show[p] = true
		}
	}
	items := []int{}
	last := 0
	for p := 1; p <= total; p++ {
		if !show[p] {
			continue
		}
		if last != 0 && p > last+1 {
			items = append(items, 0)
		}
		items = append(items, p)
		last = p
	}
	return items
}

